const inItem = $input.first().json;
const body = inItem.body || inItem;
const record_id = body.record_id
  || (body.record && body.record.id)
  || (body.records && body.records[0] && body.records[0].id)
  || (body.fields && body.fields.record_id)
  || '';
if (!record_id || !/^rec[A-Za-z0-9]{14}$/.test(record_id)) throw new Error('missing_or_invalid_record_id');
return { json: { record_id, raw: body } };

const order = $('Fetch Order').first().json;
const customer = $('Fetch Customer').first().json;
const lineItems = ($('Fetch Line Items').first().json.records) || [];

const validPayment = ['GoCardless DD', '7-day credit'];
const orderFields = order.fields || {};
const customerFields = customer.fields || {};

const dispatchStatus = orderFields['출하 상태'];
const paymentTerm = customerFields['Payment term'] || '';
const xeroContactID = customerFields['Xero ContactID'] || '';
const existingInvoiceId = orderFields['Xero 인보이스 ID'] || '';
const customerGroup = customerFields['고객 그룹'] || '일반고객';

if (dispatchStatus !== '출하완료') return { json: { should_proceed: false, skip_reason: 'not_dispatched', dispatch_status: dispatchStatus } };
if (!validPayment.includes(paymentTerm)) return { json: { should_proceed: false, skip_reason: 'payment_term_routed_to_other_wf', payment_term: paymentTerm } };
if (!xeroContactID) return { json: { should_proceed: false, skip_reason: 'xero_contact_missing' } };
if (existingInvoiceId) return { json: { should_proceed: false, skip_reason: 'already_invoiced', xero_invoice_id: existingInvoiceId } };
if (lineItems.length === 0) return { json: { should_proceed: false, skip_reason: 'no_line_items' } };

return { json: {
  should_proceed: true,
  order_id: order.id,
  order_no: orderFields['주문번호'],
  payment_term: paymentTerm,
  xero_contact_id: xeroContactID,
  customer_group: customerGroup,
  line_count: lineItems.length
} };

const order = $('Fetch Order').first().json;
const lineRecords = ($('Fetch Line Items').first().json.records) || [];
const safety = $json;
const orderFields = order.fields || {};
const orderNo = orderFields['주문번호'];
const xeroContactID = safety.xero_contact_id;
const paymentTerm = safety.payment_term;

const lineItems = [];
let subtotal = 0;
for (const lineR of lineRecords) {
  const f = lineR.fields || {};
  const qty = f['수량'] || 0;
  const unitPrice = f['단가'] || 0;
  const label = f['label'] || '';
  const skuMatch = label.match(/-([A-Z]+)$/);
  const itemCode = skuMatch ? skuMatch[1] : '';
  const lineSubtotal = qty * unitPrice;
  subtotal += lineSubtotal;
  lineItems.push({
    ItemCode: itemCode,
    Description: label,
    Quantity: qty,
    UnitAmount: unitPrice,
    TaxType: 'EXEMPTOUTPUT'
  });
}

if (subtotal < 300) {
  lineItems.push({
    Description: 'Delivery fee',
    Quantity: 1,
    UnitAmount: 5,
    TaxType: 'OUTPUT',
    DiscountRate: 0
  });
}

const today = new Date();
const todayISO = today.toISOString().slice(0, 10);
let dueDate = new Date(today);
if (paymentTerm === 'GoCardless DD') {
  const day = today.getDay();
  let daysToAdd;
  if (day === 1 || day === 2) daysToAdd = 7 + (2 - day);
  else if (day === 0) daysToAdd = 2;
  else daysToAdd = (2 - day + 7) % 7;
  dueDate.setDate(today.getDate() + daysToAdd);
} else if (paymentTerm === '7-day credit') {
  dueDate.setDate(today.getDate() + 7);
}
const dueISO = dueDate.toISOString().slice(0, 10);

const invoiceBody = {
  Invoices: [{
    Type: 'ACCREC',
    Contact: { ContactID: xeroContactID },
    Date: todayISO,
    DueDate: dueISO,
    Reference: orderNo ? ('ORD-' + orderNo) : '',
    Status: 'AUTHORISED',
    LineAmountTypes: 'Exclusive',
    LineItems: lineItems
  }]
};

return { json: {
  invoice_body_str: JSON.stringify(invoiceBody),
  subtotal,
  delivery_fee: subtotal < 300 ? 5 : 0,
  due_date: dueISO,
  order_id: safety.order_id,
  order_no: orderNo,
  line_count: lineItems.length
} };

